#!/usr/bin/env bash
# Generate the 1M-row, single-encoding inputs `--throughput` measures.
#
# 468 MB for 57 encodings, so they are not committed -- bench/README.md and ThroughputCheck.cs both
# say why. They go in a CACHE directory rather than /tmp: a reboot wiping them is how a corpus gets
# regenerated by accident, and a regenerated corpus is exactly what the manifest exists to catch.
#
# Takes a few minutes. Run it once; `--throughput` finds them by itself afterwards.
set -euo pipefail

rows="${1:-1000000}"
out="${VORTICITY_THROUGHPUT_CORPUS:-$HOME/.cache/vorticity/throughput-1M}"
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

echo "generating $rows-row inputs into $out"
mkdir -p "$out"
cd "$here/../tools/conformance-gen"
cargo run --release -j 6 -- --throughput "$rows" --out "$out"

echo
echo "done. Measure with:"
echo "  dotnet run -c Release --project bench/Vorticity.Benchmarks -- --throughput --check"
